using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using PokeMarketApi.Data;using PokeMarketApi.Models;namespace PokeMarketApi.Controllers;[Authorize]public class PortfolioController(MarketContext db,UserManager<IdentityUser> users):Controller{public async Task<IActionResult> Index()=>View(await db.PortfolioItems.Where(x=>x.UserId==users.GetUserId(User)).ToListAsync());[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Add(string productName,string? imageUrl,string? setName,string grade,decimal currentValueQar){db.PortfolioItems.Add(new PortfolioItem{UserId=users.GetUserId(User)!,ProductName=productName,ImageUrl=imageUrl,SetName=setName,Grade=grade,CurrentValueQar=currentValueQar});await db.SaveChangesAsync();return RedirectToAction(nameof(Index));}[HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Remove(int id){var x=await db.PortfolioItems.FirstOrDefaultAsync(a=>a.Id==id&&a.UserId==users.GetUserId(User));if(x!=null){db.Remove(x);await db.SaveChangesAsync();}return RedirectToAction(nameof(Index));}}